'use strict';

function createDeepProxy(obj) {
    return new Proxy(obj, {
        get(target, prop) {
            if (typeof prop !== 'string') return target[prop];

            
            if (prop.includes('.')) {
                const parts = prop.split('.');
                let curr = target;
                for (const part of parts) {
                    if (curr && typeof curr === 'object' && part in curr) {
                        curr = curr[part];
                    } else {
                        curr = undefined;
                        break;
                    }
                }
                if (curr !== undefined) {
                    return (curr && typeof curr === 'object') ? createDeepProxy(curr) : curr;
                }
            }

            if (prop in target) {
                const val = target[prop];
                if (val && typeof val === 'object') return createDeepProxy(val);
                return val;
            }

            
            return prop
                .replace(/([A-Z])/g, ' $1')
                .replace(/^./, str => str.toUpperCase())
                .trim();
        },
    });
}

